#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

#
# Smart Recipe first Google Play release: walks the 7 owner-only steps of
# PLAY-STORE-DEPLOY.md §0, in order, with the same commands and Play Console
# paths. Run it from anywhere:
#
#   projects/smart-recipe-app/store-listing/release-wizard.sh            # real run
#   projects/smart-recipe-app/store-listing/release-wizard.sh --dry-run  # preview only
#
# Safety rules this script keeps:
#   - The keystore and the downloaded .aab live OUTSIDE any git repo.
#   - Passwords are typed at keytool's own prompt or read with `read -rs`,
#     then piped to `gh secret set` with the printf builtin: never echoed,
#     never written to disk, never on a command line.
#   - The progress file holds step numbers and dates only, never secrets.
#   - Linux (GNU coreutils) assumed: `base64 -w0`, `date -d`, `realpath -m`.

TOTAL_STAGES=7

REPO_SLUG="jf1shh/agentic-app-harness"
WORKFLOW_FILE="android-release-smart-recipe-app.yml"
ARTIFACT_NAME="smart-recipe-app-release-aab"
SECRET_SUFFIX="_SMART_RECIPE_APP"
KEY_ALIAS="upload"
KEY_DNAME="CN=Smart Recipe, OU=Mobile, O=Agentic App Harness, C=US"
CONSOLE_URL="https://play.google.com/console"
PRIVACY_URL="https://jf1shh.github.io/agentic-app-harness/smart-recipe-app/privacy.html"
PR_URL="https://github.com/jf1shh/agentic-app-harness/pull/408"

SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
LISTING_README="$SCRIPT_DIR/README.md"
STATE_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/smart-recipe-release"
STATE_FILE="$STATE_DIR/progress"
KEYSTORE="${SMART_RECIPE_KEYSTORE:-$HOME/keys/smart-recipe-upload.jks}"
DOWNLOAD_BASE="${SMART_RECIPE_DOWNLOAD_DIR:-$HOME/Downloads/smart-recipe-release}"

STEP_TITLES=(
  ""
  "Make the upload key (keystore)"
  "Add the 4 GitHub secrets and build a signed bundle"
  "Play Console: create the app and fill in its pages"
  "Upload the bundle to closed testing"
  "Recruit 12+ real testers"
  "Wait 14 days in a row"
  "Apply for production"
)

DRY_RUN=0
FROM_STEP=0
DO_RESET=0

usage() {
  cat <<EOF
Smart Recipe release wizard: walks the 7 owner-only steps in PLAY-STORE-DEPLOY.md §0.

Usage: $(basename "$0") [options]

  --dry-run         Print every command instead of running it. No keys, no
                    network, no GitHub changes, no progress saved. Never waits
                    for input.
  --from N          Start at step N (1-7). Steps before N are skipped; N and
                    later run again even if marked done.
  --reset           Forget saved progress, then start at step 1.
  --keystore PATH   Where the upload keystore lives (must be outside any git repo).
                    Default: $KEYSTORE
  -h, --help        Show this help.

Environment:
  SMART_RECIPE_KEYSTORE      same as --keystore
  SMART_RECIPE_DOWNLOAD_DIR  where the .aab is downloaded (default: $DOWNLOAD_BASE)
  XDG_STATE_HOME             progress lives in \$XDG_STATE_HOME/smart-recipe-release/progress

Progress file (step numbers and dates only): $STATE_FILE

Steps:
  1. ${STEP_TITLES[1]}
  2. ${STEP_TITLES[2]}
  3. ${STEP_TITLES[3]}
  4. ${STEP_TITLES[4]}
  5. ${STEP_TITLES[5]}
  6. ${STEP_TITLES[6]}
  7. ${STEP_TITLES[7]}
EOF
}

while (( $# )); do
  case "$1" in
    -h|--help) usage; exit 0 ;;
    --dry-run) DRY_RUN=1 ;;
    --reset) DO_RESET=1 ;;
    --from) [[ $# -ge 2 ]] || { usage >&2; exit 2; }; FROM_STEP="$2"; shift ;;
    --from=*) FROM_STEP="${1#--from=}" ;;
    --keystore) [[ $# -ge 2 ]] || { usage >&2; exit 2; }; KEYSTORE="$2"; shift ;;
    --keystore=*) KEYSTORE="${1#--keystore=}" ;;
    *) printf 'Unknown option: %s\n\n' "$1" >&2; usage >&2; exit 2 ;;
  esac
  shift
done

if ! [[ "$FROM_STEP" =~ ^[0-7]$ ]]; then
  printf 'The --from step must be a number from 1 to 7 (got "%s").\n' "$FROM_STEP" >&2
  exit 2
fi

# ── Small helpers built on the library ────────────────────────────────────

is_dry() { (( DRY_RUN == 1 )); }

# show_cmd "text" prints a command the way the dry-run reports it.
show_cmd() { printf '  %s[dry-run] would run:%s %s\n' "$DIM" "$RESET" "$1"; }

# quote_arg ARG prints ARG as you would type it (single quotes when needed).
quote_arg() {
  if [[ "$1" =~ ^[A-Za-z0-9_./:=@%+,~-]+$ ]]; then
    printf '%s' "$1"
  else
    printf "'%s'" "${1//\'/\'\\\'\'}"
  fi
}

# run_cmd CMD ARGS... runs a command, or prints it (shell-quoted) in dry-run.
run_cmd() {
  if is_dry; then
    local arg quoted=""
    for arg in "$@"; do quoted+="$(quote_arg "$arg") "; done
    show_cmd "${quoted% }"
    return 0
  fi
  "$@"
}

# gate "message" waits for Enter (skipped in dry-run).
gate() {
  if is_dry; then note "[dry-run] would wait: $1"; return 0; fi
  pause "$1"
}

# yes_no "question" [y|n] is a y/N gate. In dry-run it never reads input and
# takes the given answer (default y) so the whole walk-through prints.
yes_no() {
  if is_dry; then
    note "[dry-run] would ask: $1 (taking '${2:-y}')"
    [[ "${2:-y}" == y ]]
    return
  fi
  confirm "$1"
}

# open_link URL opens the browser, or just prints the URL in dry-run.
open_link() {
  if is_dry; then note "[dry-run] would open: $1"; return 0; fi
  open_url "$1"
}

die() { printf '\n  %s✗ %s%s\n' "$RED" "$1" "$RESET"; exit 1; }

# stop_here "why" ends the run cleanly; progress so far is kept.
stop_here() {
  printf '\n'
  say "$1"
  if is_dry; then
    note "[dry-run] a real run would stop here."
  else
    note "Your progress is saved. Run this wizard again to pick up here."
  fi
  exit 0
}

# stage_at N "title" shows "Stage N/7" even when earlier steps were skipped.
stage_at() { _STAGE_INDEX=$(( $1 - 1 )); stage "$2"; }

# ── Progress file: "key value" lines, step numbers and dates only ─────────

state_get() {
  [[ -f "$STATE_FILE" ]] || return 0
  awk -v k="$1" '$1 == k { v = $2 } END { if (v != "") print v }' "$STATE_FILE"
}

state_set() {
  if is_dry; then note "[dry-run] would save progress: $1 $2"; return 0; fi
  local tmp
  mkdir -p "$STATE_DIR"
  chmod 700 "$STATE_DIR"
  touch "$STATE_FILE"
  tmp=$(mktemp "$STATE_DIR/progress.XXXXXX")
  awk -v k="$1" '$1 != k' "$STATE_FILE" > "$tmp"
  printf '%s %s\n' "$1" "$2" >> "$tmp"
  mv "$tmp" "$STATE_FILE"
}

mark_done() {
  state_set "done-$1" "$(date +%F)"
  printf '  %s✓ step %s done%s\n' "$GREEN" "$1" "$RESET"
}

earliest_apply_date() { date -d "$1 + 14 days" +%F; }

# days_until YYYY-MM-DD prints whole days from today (negative if past).
days_until() {
  local now target
  now=$(date -d "$(date +%F)" +%s)
  target=$(date -d "$1" +%s)
  printf '%s' $(( (target - now) / 86400 ))
}

# ── Preflight checks ──────────────────────────────────────────────────────

jdk_hint() {
  note "keytool and jarsigner come with a Java JDK. Install one, for example:"
  note "  Arch/CachyOS:  sudo pacman -S jdk-openjdk"
  note "  Debian/Ubuntu: sudo apt install openjdk-17-jdk-headless"
  note "  macOS:         brew install openjdk"
}

# need_tool NAME: stop with an install hint if NAME is missing.
need_tool() {
  command -v "$1" >/dev/null 2>&1 && return 0
  warn "This step needs '$1', and it is not installed."
  case "$1" in
    keytool|jarsigner) jdk_hint ;;
    gh) note "Install the GitHub CLI: sudo pacman -S github-cli (Arch) or see https://cli.github.com" ;;
    base64|realpath|date) note "'$1' is part of GNU coreutils: sudo pacman -S coreutils (Arch) or sudo apt install coreutils" ;;
    git) note "Install git: sudo pacman -S git (Arch) or sudo apt install git" ;;
  esac
  if is_dry; then note "[dry-run] carrying on anyway"; return 0; fi
  exit 1
}

need_gh_auth() {
  if is_dry; then show_cmd "gh auth status"; return 0; fi
  if ! gh auth status >/dev/null 2>&1; then
    warn "The GitHub CLI is not logged in."
    say "Run this, then start the wizard again:  gh auth login"
    exit 1
  fi
}

# repo_containing PATH prints the git repo PATH would sit in, if any. It
# walks up to the nearest folder that exists, since PATH may not exist yet.
repo_containing() {
  local dir
  dir=$(dirname "$(realpath -m -- "$1")")
  while [[ ! -d "$dir" ]]; do dir=$(dirname "$dir"); done
  if git -C "$dir" rev-parse --git-dir >/dev/null 2>&1; then
    git -C "$dir" rev-parse --show-toplevel 2>/dev/null || printf '%s' "$dir"
  fi
}

# require_outside_repo PATH WHAT: refuse anything that would land in a repo.
require_outside_repo() {
  local repo
  repo=$(repo_containing "$1")
  if [[ -n "$repo" ]]; then
    die "Refusing: $2 at $1 would sit inside the git repo $repo. Pick a folder outside any repo (use --keystore PATH or SMART_RECIPE_DOWNLOAD_DIR)."
  fi
}

# ── Step 1: upload keystore ───────────────────────────────────────────────

step_1() {
  stage_at 1 "${STEP_TITLES[1]}"
  need_tool keytool
  need_tool git
  require_outside_repo "$KEYSTORE" "the keystore"
  say "The upload key proves to Google that a new version really comes from you."
  say "Keystore file: $KEYSTORE"
  printf '\n'

  if [[ -f "$KEYSTORE" ]]; then
    say "That file already exists, so no new key is made."
  else
    say "keytool will ask for a password, then ask you to type it again."
    step "Pick one strong password and save it in your password manager first."
    step "If keytool also asks for a separate key password, press Enter to use the same one."
    printf '\n'
    yes_no "Make the keystore now?" || stop_here "No keystore made."
    local dir
    dir=$(dirname "$KEYSTORE")
    if [[ ! -d "$dir" ]]; then
      run_cmd mkdir -p "$dir"
      run_cmd chmod 700 "$dir"
    fi
    run_cmd keytool -genkeypair -v -keystore "$KEYSTORE" -alias "$KEY_ALIAS" \
      -keyalg RSA -keysize 2048 -validity 10000 -dname "$KEY_DNAME"
    run_cmd chmod 600 "$KEYSTORE"
  fi

  printf '\n'
  say "Now a quick check that the key is there. Type the keystore password when asked."
  if ! run_cmd keytool -list -keystore "$KEYSTORE" -alias "$KEY_ALIAS"; then
    stop_here "That check failed: wrong password, or no key named '$KEY_ALIAS' in $KEYSTORE."
  fi

  printf '\n'
  warn "Back it up now. This file plus its password is the only way to ship Smart Recipe updates."
  step "Copy $KEYSTORE to two safe places (for example your password manager and an encrypted drive)."
  step "Save the password in your password manager."
  note "If you lose it, Google can reset the upload key, but that takes a support request and days."
  gate "Press Enter once the keystore is backed up and the password is saved."
  mark_done 1
}

# ── Step 2: GitHub secrets, then the signed build ─────────────────────────

# read_keystore_password VAR: hidden prompt, checked against the keystore via
# keytool's -storepass:env so the password never reaches a command line.
read_keystore_password() {
  local pw="" tries=0
  while (( tries < 3 )); do
    printf '  %sKeystore password (hidden):%s ' "$BOLD" "$RESET"
    IFS= read -rs pw || true
    printf '\n'
    if [[ -n "$pw" ]] && SMART_RECIPE_KS_PW="$pw" keytool -list -keystore "$KEYSTORE" \
        -alias "$KEY_ALIAS" -storepass:env SMART_RECIPE_KS_PW >/dev/null 2>&1; then
      printf -v "$1" '%s' "$pw"
      return 0
    fi
    warn "That password does not open $KEYSTORE. Try again."
    tries=$((tries + 1))
  done
  die "Three wrong tries. Run the wizard again when you have the password."
}

# set_secret_from_var NAME VAR pipes a password to gh with the printf builtin
# (builtins never show up in the process list).
set_secret_from_var() {
  local name="$1" var="$2"
  if is_dry; then show_cmd "printf '%s' \"\$$var\" | gh secret set $name --repo $REPO_SLUG"; return 0; fi
  printf '%s' "${!var}" | gh secret set "$name" --repo "$REPO_SLUG"
  WRITTEN_SECRET+=("$name")
}

step_2_secrets() {
  stage_at 2 "Add the 4 GitHub secrets (part 1 of 2)"
  need_tool gh
  need_tool base64
  need_tool keytool
  need_tool git
  need_gh_auth
  require_outside_repo "$KEYSTORE" "the keystore"
  if ! is_dry && [[ ! -f "$KEYSTORE" ]]; then
    die "No keystore at $KEYSTORE. Run step 1 first (or pass --keystore PATH)."
  fi
  say "GitHub needs the keystore and its passwords so it can sign the app for you."
  say "Repo: $REPO_SLUG. Nothing is written to disk."
  printf '\n'

  local have=0
  if is_dry; then
    show_cmd "gh secret list --repo $REPO_SLUG --json name --jq '.[].name'"
  else
    have=$(gh secret list --repo "$REPO_SLUG" --json name --jq '.[].name' | grep -c -- "${SECRET_SUFFIX}\$" || true)
  fi
  if (( have >= 4 )); then
    say "All 4 ${SECRET_SUFFIX} secrets are already set."
    if ! yes_no "Replace them anyway?" n; then
      say "Keeping the secrets you have."
      gate "Press Enter to go on to the build."
      return 0
    fi
  fi

  say "First the passwords (typing is hidden). They are checked before anything is sent."
  local store_pw="" key_pw=""
  if is_dry; then
    note "[dry-run] would read the keystore password with read -rs and check it with keytool -storepass:env"
  else
    read_keystore_password store_pw
  fi
  note "If you used one password at keytool (the usual case), the key password is the same."
  if yes_no "Did you set a DIFFERENT password for the key itself?" n; then
    if is_dry; then
      note "[dry-run] would read the key password with read -rs"
    else
      printf '  %sKey password (hidden):%s ' "$BOLD" "$RESET"
      IFS= read -rs key_pw || true
      printf '\n'
      [[ -n "$key_pw" ]] || die "Empty key password. Nothing was set; run step 2 again."
    fi
  else
    key_pw="$store_pw"
  fi

  printf '\n'
  say "1/4: the keystore file itself."
  if is_dry; then
    show_cmd "base64 -w0 $KEYSTORE | gh secret set ANDROID_KEYSTORE_BASE64${SECRET_SUFFIX} --repo $REPO_SLUG"
  else
    base64 -w0 -- "$KEYSTORE" | gh secret set "ANDROID_KEYSTORE_BASE64${SECRET_SUFFIX}" --repo "$REPO_SLUG"
    WRITTEN_SECRET+=("ANDROID_KEYSTORE_BASE64${SECRET_SUFFIX}")
  fi
  say "2/4: the keystore password."
  set_secret_from_var "ANDROID_KEYSTORE_PASSWORD${SECRET_SUFFIX}" store_pw
  say "3/4: the key password."
  set_secret_from_var "ANDROID_KEY_PASSWORD${SECRET_SUFFIX}" key_pw
  store_pw=""; key_pw=""
  unset store_pw key_pw

  say "4/4: the key name ('$KEY_ALIAS')."
  run_cmd gh secret set "ANDROID_KEY_ALIAS${SECRET_SUFFIX}" --repo "$REPO_SLUG" --body "$KEY_ALIAS"
  is_dry || WRITTEN_SECRET+=("ANDROID_KEY_ALIAS${SECRET_SUFFIX}")

  printf '\n'
  say "Check (names only, never values):"
  if is_dry; then
    show_cmd "gh secret list --repo $REPO_SLUG | grep ${SECRET_SUFFIX}"
  else
    gh secret list --repo "$REPO_SLUG" | grep -- "$SECRET_SUFFIX" || true
    have=$(gh secret list --repo "$REPO_SLUG" --json name --jq '.[].name' | grep -c -- "${SECRET_SUFFIX}\$" || true)
    (( have >= 4 )) || die "Expected 4 ${SECRET_SUFFIX} secrets, found $have. Run step 2 again."
  fi
  gate "Press Enter to go on to the build."
}

step_2_build() {
  stage_at 2 "Build and check the signed bundle (part 2 of 2)"
  need_tool gh
  need_tool jarsigner
  need_tool git
  need_gh_auth
  local dl_check="$DOWNLOAD_BASE/run-check/x.aab"
  require_outside_repo "$dl_check" "the download folder"

  # Before PR #408 merges, master's workflow reads the unsuffixed secrets and
  # would build an UNSIGNED bundle, so check master first.
  say "Checking that master's workflow reads the ${SECRET_SUFFIX} secrets..."
  if is_dry; then
    show_cmd "gh api -H 'Accept: application/vnd.github.raw' repos/$REPO_SLUG/contents/.github/workflows/$WORKFLOW_FILE?ref=master | grep 'secret_suffix: $SECRET_SUFFIX'"
  elif ! gh api -H "Accept: application/vnd.github.raw" \
      "repos/$REPO_SLUG/contents/.github/workflows/$WORKFLOW_FILE?ref=master" \
      | grep -q -- "secret_suffix: $SECRET_SUFFIX"; then
    warn "master does not read the ${SECRET_SUFFIX} secrets yet, so the build would come out UNSIGNED."
    say "Merge $PR_URL first, then run:  $0 --from 2"
    stop_here "Stopped before starting a build."
  fi

  say "GitHub will build the app and sign it with your key. It takes about 10 to 15 minutes."
  yes_no "Start the build on GitHub now?" || stop_here "No build started."

  local run_id="" since out
  since=$(date -u -d '-30 seconds' +%Y-%m-%dT%H:%M:%SZ)
  if is_dry; then
    show_cmd "gh workflow run $WORKFLOW_FILE --repo $REPO_SLUG --ref master"
    show_cmd "gh run list --repo $REPO_SLUG --workflow $WORKFLOW_FILE --event workflow_dispatch --branch master -L 5 --json databaseId,createdAt  (newest run created after $since)"
    run_id="RUN_ID"
  else
    out=$(gh workflow run "$WORKFLOW_FILE" --repo "$REPO_SLUG" --ref master 2>&1) || die "Could not start the build: $out"
    printf '  %s\n' "$out"
    run_id=$(printf '%s' "$out" | grep -oE 'actions/runs/[0-9]+' | head -n1 | cut -d/ -f3 || true)
    local tries=0
    while [[ -z "$run_id" && $tries -lt 24 ]]; do
      sleep 5
      run_id=$(gh run list --repo "$REPO_SLUG" --workflow "$WORKFLOW_FILE" --event workflow_dispatch \
        --branch master -L 5 --json databaseId,createdAt \
        --jq "map(select(.createdAt >= \"$since\")) | .[0].databaseId // empty" || true)
      tries=$((tries + 1))
    done
    if [[ -z "$run_id" ]]; then
      warn "Could not find the new run by itself."
      say "Find it with:  gh run list --workflow $WORKFLOW_FILE --repo $REPO_SLUG -L 1"
      printf '  %sType the run id:%s ' "$BOLD" "$RESET"
      read -r run_id || true
      [[ "$run_id" =~ ^[0-9]+$ ]] || die "That is not a run id."
    fi
  fi
  say "Run page: https://github.com/$REPO_SLUG/actions/runs/$run_id"

  printf '\n'
  say "Watching the build (Ctrl-C stops watching; the build keeps going on GitHub)..."
  if ! run_cmd gh run watch "$run_id" --repo "$REPO_SLUG" --exit-status; then
    warn "The build failed. Open the run page above to see why."
    stop_here "Fix it, then run:  $0 --from 2"
  fi

  # The run summary says "Built a SIGNED release bundle." exactly when the
  # "Decode upload keystore" step ran, so its conclusion is the CLI-readable
  # version of that line.
  local signed="success"
  if is_dry; then
    show_cmd "gh run view $run_id --repo $REPO_SLUG --json jobs --jq '<conclusion of the \"Decode upload keystore\" step>'"
  else
    signed=$(gh run view "$run_id" --repo "$REPO_SLUG" --json jobs \
      --jq '[.jobs[].steps[] | select(.name == "Decode upload keystore") | .conclusion] | first // "missing"')
  fi
  if [[ "$signed" != "success" ]]; then
    warn "This build is UNSIGNED (keystore step: $signed). Play will not accept it."
    stop_here "Check the 4 secrets (step 2), then run:  $0 --from 2"
  fi
  say "Signed. The run page summary should read: Built a SIGNED release bundle."

  local dir="$DOWNLOAD_BASE/run-$run_id" aab=""
  require_outside_repo "$dir/x.aab" "the download folder"
  printf '\n'
  say "Downloading the bundle to $dir"
  run_cmd mkdir -p "$dir"
  run_cmd gh run download "$run_id" --repo "$REPO_SLUG" -n "$ARTIFACT_NAME" -D "$dir"

  if is_dry; then
    aab="$dir/app-release.aab"
    show_cmd "jarsigner -verify -verbose -certs $aab   (look for 'jar verified.' and 'CN=Smart Recipe')"
  else
    aab=$(find "$dir" -name '*.aab' -print -quit)
    [[ -n "$aab" ]] || die "No .aab file in $dir."
    local report
    report=$(jarsigner -verify -verbose -certs "$aab" 2>&1 || true)
    if grep -q "jar verified" <<<"$report" && grep -q "CN=Smart Recipe" <<<"$report"; then
      say "jarsigner: jar verified, signed by:"
      grep -m1 "CN=Smart Recipe" <<<"$report" | sed 's/^[[:space:]]*/    /'
    else
      warn "jarsigner did not confirm a Smart Recipe signature. Last lines:"
      tail -n 5 <<<"$report" | sed 's/^/    /'
      stop_here "Do not upload this file. Check the secrets, then run:  $0 --from 2"
    fi
  fi
  printf '\n'
  say "Your upload file: $aab"
  gate "Press Enter to finish step 2."
  mark_done 2
}

step_2() {
  step_2_secrets
  step_2_build
}

# ── Steps 3-7: Play Console checklists ────────────────────────────────────

step_3() {
  stage_at 3 "${STEP_TITLES[3]}"
  say "Every answer is in: $LISTING_README"
  open_link "$CONSOLE_URL"
  printf '\n'
  step "Home → Create app: name Smart Recipe, default language English (US), App, Free."
  step "Grow users → Store presence → Main store listing: short + full description,"
  note "    icon (icon-512.png), feature graphic, the 5 phone screenshots. Category: Food & Drink."
  note "    The image files are in $SCRIPT_DIR"
  step "Policy and programs → App content:"
  note "    Privacy policy: $PRIVACY_URL"
  note "    App access: All functionality is available without special access"
  note "    Ads: No"
  note "    Content rating: the IARC answers from the README"
  note "    Target audience: 13+ (not designed for children)"
  note "    Data safety: the README's option 1 (declares in-app search text) unless you prefer option 2"
  step "Test and release → Setup → App signing: accept Play App Signing."
  note "    Google keeps the app signing key; your keystore from step 1 is the upload key."
  printf '\n'
  yes_no "Have you finished every item above?" || stop_here "Finish the items above, then run the wizard again."
  mark_done 3
}

latest_aab() {
  [[ -d "$DOWNLOAD_BASE" ]] || return 0
  find "$DOWNLOAD_BASE" -name '*.aab' -printf '%T@ %p\n' 2>/dev/null | sort -rn | head -n1 | cut -d' ' -f2-
}

step_4() {
  stage_at 4 "${STEP_TITLES[4]}"
  local aab
  aab=$(latest_aab)
  say "The file to upload: ${aab:-the .aab from step 2 (look in $DOWNLOAD_BASE)}"
  open_link "$CONSOLE_URL"
  printf '\n'
  step "Test and release → Testing → Closed testing → Create track"
  note "    (or use the default 'Closed testing - Alpha')."
  step "Testers tab → add an email list."
  step "Create new release → upload the .aab → Next → Save → Start rollout."
  step "Countries / regions tab: choose the countries."
  printf '\n'
  yes_no "Is the closed testing release rolled out?" || stop_here "Finish the upload, then run the wizard again."
  mark_done 4
}

step_5() {
  stage_at 5 "${STEP_TITLES[5]}"
  open_link "$CONSOLE_URL"
  step "Copy the opt-in link from the Testers tab of your closed testing track."
  step "Send it to real people with Android phones. Ask for 15 to 20, so one dropout does not reset the count."
  step "Each tester opens the link, taps 'Become a tester', then installs Smart Recipe from Play."
  warn "Only real people count. Bots, AI agents, emulators or your own extra accounts do not."
  printf '\n'
  local count=15
  if is_dry; then
    note "[dry-run] would ask how many testers have opted in (taking 15)"
  else
    printf '  %sHow many real testers have opted in so far?%s ' "$BOLD" "$RESET"
    read -r count || true
    [[ "$count" =~ ^[0-9]+$ ]] || count=0
  fi
  if (( count < 12 )); then
    stop_here "You need at least 12 (15 to 20 is safer). Run the wizard again when you have them."
  fi
  say "$count testers. The 14-day clock can start."
  gate "Press Enter to go on."
  mark_done 5
}

# ask_start_date: prints a YYYY-MM-DD the owner gives (Enter = today).
ask_start_date() {
  local input=""
  printf '  %sWhat day did you reach 12 opted-in testers? [Enter = today, or YYYY-MM-DD]%s ' "$BOLD" "$RESET" >&2
  read -r input || true
  [[ -n "$input" ]] || input=$(date +%F)
  date -d "$input" +%F 2>/dev/null || { warn "Not a date: $input. Using today." >&2; date +%F; }
}

step_6() {
  stage_at 6 "${STEP_TITLES[6]}"
  local start earliest left
  start=$(state_get wait-start)
  if [[ -z "$start" ]]; then
    say "The clock starts the day 12+ testers are opted in."
    if is_dry; then
      start=$(date +%F)
      note "[dry-run] would ask for the start date (taking today, $start)"
    else
      start=$(ask_start_date)
    fi
    state_set wait-start "$start"
  fi
  earliest=$(earliest_apply_date "$start")
  left=$(days_until "$earliest")
  say "14 days started:        $start"
  say "Earliest day to apply:  $earliest"
  printf '\n'
  step "Testers must stay opted in for 14 days in a row."
  step "Ask them to use all four screens (inventory, recipes, search, planner) and send feedback."
  note "    The production application asks about both."
  step "Meanwhile read Test and release → Testing → Pre-launch report and fix anything it flags."
  printf '\n'

  if yes_no "Did the opted-in count drop below 12 at any point?" n; then
    warn "That restarts the 14 days."
    local restart
    if is_dry; then restart=$(date +%F); else restart=$(ask_start_date); fi
    state_set wait-start "$restart"
    stop_here "New earliest day to apply: $(earliest_apply_date "$restart")."
  fi

  if (( left > 0 )); then
    if is_dry; then
      note "[dry-run] a real run would stop here: $left day(s) to go, back on or after $earliest. Showing the rest anyway."
    else
      stop_here "$left day(s) to go. Come back on or after $earliest."
    fi
  fi
  say "The 14 days are up."
  yes_no "Have 12+ testers stayed opted in the whole time?" || stop_here "Wait until they have, then run the wizard again."
  mark_done 6
}

step_7() {
  stage_at 7 "${STEP_TITLES[7]}"
  local start
  start=$(state_get wait-start)
  if [[ -n "$start" ]]; then
    local earliest
    earliest=$(earliest_apply_date "$start")
    if (( $(days_until "$earliest") > 0 )); then
      warn "The 14 days are not up until $earliest. The Apply button will not show before then."
    fi
  fi
  open_link "$CONSOLE_URL"
  step "Dashboard → Apply for production (shows once step 6 is met)."
  step "Answer all three parts: the closed test, the app, and production readiness."
  note "    Google says review usually takes seven days or less."
  step "After approval: Test and release → Production → Create new release."
  printf '\n'
  yes_no "Have you sent the production application?" || stop_here "Send it, then run the wizard again."
  mark_done 7
}

# ── Main ──────────────────────────────────────────────────────────────────

show_progress() {
  local n d start
  say "Progress file: $STATE_FILE"
  for n in 1 2 3 4 5 6 7; do
    d=$(state_get "done-$n")
    if [[ -n "$d" ]]; then
      printf '  [x] %s. %s  (done %s)\n' "$n" "${STEP_TITLES[$n]}" "$d"
    else
      printf '  [ ] %s. %s\n' "$n" "${STEP_TITLES[$n]}"
    fi
  done
  start=$(state_get wait-start)
  if [[ -n "$start" ]]; then
    printf '\n'
    say "14-day wait started $start. Earliest day to apply: $(earliest_apply_date "$start")."
  fi
  printf '\n'
}

if (( DO_RESET )); then
  if is_dry; then
    show_cmd "rm -f $STATE_FILE"
  elif [[ -f "$STATE_FILE" ]] && confirm "Forget all saved progress in $STATE_FILE?"; then
    rm -f "$STATE_FILE"
    say "Progress cleared."
  fi
fi

if is_dry; then
  printf '\n%s  Smart Recipe release wizard (DRY RUN: nothing runs, nothing is saved)%s\n\n' "$BOLD" "$RESET"
  show_progress
else
  banner "Smart Recipe: first Google Play release"
  show_progress
  gate "Press Enter to begin."
fi

for n in 1 2 3 4 5 6 7; do
  if (( FROM_STEP > 0 )); then
    (( n < FROM_STEP )) && continue
  elif [[ -n "$(state_get "done-$n")" ]]; then
    continue
  fi
  "step_$n"
done

finish
say "All 7 steps are done. Smart Recipe is with Google for production review."
